#include <stdio.h>

void sumRow(int arr[], int n) {         // 'int arr[]' here really means 'int *arr'
    int total = 0;
    for (int *p = arr; p < arr + n; p++) {   // pointer-based traversal
        total += *p;
    }
    printf("%d\n", total);
}

void printGrid(int grid[][3], int rows) {  // inner dimension (3) is required
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < 3; j++) {
            printf("%d ", grid[i][j]);
        }
    }
    printf("\n");
}

int main() {
    int nums[] = {1, 2, 3, 4};
    sumRow(nums, 4);

    int grid[2][3] = {{1, 2, 3}, {4, 5, 6}};
    printGrid(grid, 2);
    return 0;
}
